-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["783a62167b79083f"] = { "Sbigottito, Doomhammer, che per il tradimento di Gul'dan aveva perso quasi metà delle sue forze, fu costretto a ritirarsi e a rinunciare alla sua più grande occasione di vittoria sull'⟦Alliance=Alleanza⟧.", "." },
  ["784078927445c977"] = { "Anzi, spesso si comportava esattamente al contrario di come ci si aspettava! Era quasi come se il pendente mandasse a monte di proposito i miei esperimenti.\n\nCome se pensasse, e fosse vivo.\n\nIrritato ma non scoraggiato, smisi di considerare il pendente un pezzo di roccia inerte e cominciai a considerarlo un essere vivente.\n\nMa, ancora una volta, fallii.", "." },
  ["786aaf2e2b4064ae"] = { "Con la ⟦Holy Light=Luce Sacra⟧ che ci scalda le spalle e nuove scoperte ogni giorno, è un periodo entusiasmante per chi appartiene al popolo di Forgiardente. La Lega degli Esploratori fa progressi ogni giorno nella ricerca di risposte perdute da tempo a domande ancora più antiche. E ora abbiamo anche te tra i nostri fedeli, per aiutarci nella battaglia contro i trogg e contro ogni altra minaccia ai nostri confini.\n\nCercami quando hai tempo. Sarò nel retro di ⟦Anvilmar=Forgiamara⟧, appena su per la collina.\n\n- Branstock Khalder, istruttore dei sacerdoti", "." },
  ["786baadf32a4c009"] = { "Capitano dei ranger Alleria Windrunner\n\nRinomata cacciatrice di troll di Quel'Thalas. Capo esploratrice e agente dei servizi segreti della Spedizione dell'⟦Alliance=Alleanza⟧ che marciò su Draenor, il mondo natale degli orchi. Presunta morta.\n\nIl tuo cuore volava dritto come una freccia nel vento, sorella. Eri la più luminosa del nostro Ordine. Eri la più amata della nostra stirpe.\n\n- Sylvanas Windrunner - Generale dei ranger di Quel'Thalas", "." },
  ["787b99cb0be1b70a"] = { "Portami questi tre oggetti, la Stella, l'Artiglio e il Cuore, e il ⟦Yagyin's Digest=Compendio di Yagyin⟧ sarà tuo.\n\n-G.B.", "." },
  ["787f8cee9bbbbd52"] = { "Min'loth urlò, e la sua magia raccolse il potere degli incantesimi dei suoi servitori, e lui lo scagliò contro i Krakken che avanzavano.\n\nI mari si aprirono e l'incantesimo di Min'loth sfrecciò verso i servitori di Neptulon. Fulmini squarciarono il cielo e l'incantesimo li colpì, e caddero mille saette, che fecero bollire l'acqua e scavarono crateri ardenti nella terra.\n\nMin'loth gridò in trionfo, certo che il suo incantesimo avrebbe abbattuto le grandi bestie.", "." },
  ["788050816777ea0c"] = { "--Terzo giorno--\n\nOh, grande e splendida scoperta!\n\nEsplorando oggi mi sono imbattuto in un ritrovamento grandioso: gli enormi resti di quella che sembra essere stata una creatura simile a un cinghiale. Il suo teschio torreggiava per molte lunghezze sopra di me. Ogni dente della bestia avrebbe fatto sembrare piccolo persino... be', un nano. Date le dimensioni del ritrovamento, sono portato a credere che siano i resti di uno dei leggendari Dei Antichi.", "." },
  ["78df567007b1a4ac"] = { "Alla fine Hellscream riscattò il suo onore aiutando Thrall a sconfiggere Mannoroth, il signore dei demoni che per primo aveva maledetto gli orchi con la sua stirpe di odio e di furia. Con la morte di Mannoroth, la maledizione del sangue degli orchi ebbe finalmente fine.", "." },
  ["78fb356c5c701894"] = { "Benché la spada gli concedesse un potere insondabile, gli rubò anche l'anima e lo trasformò nel più grande dei cavalieri della morte del Re dei Lich. Con l'anima perduta e la mente in frantumi, Arthas guidò il Flagello contro il suo stesso regno. Alla fine Arthas uccise il proprio padre, re Terenas, e schiacciò Lordaeron sotto il tallone di ferro del Re dei Lich.", "." },
})
